// Prepara uma requisição CAPI por item reservado na fila.
let payload = $json.payload;

if (typeof payload === 'string') {
  payload = JSON.parse(payload);
}

const versaoBruta = String($json.graph_api_version || 'v25.0').trim();
const versao = versaoBruta.startsWith('v') ? versaoBruta : `v${versaoBruta}`;
const datasetId = String($json.dataset_id || '').trim();

if (!datasetId) {
  throw new Error(`Dataset ID ausente para ${$json.chave_cliente || 'cliente'}`);
}

const payloadEnvio = { ...payload };
const codigoTeste = String($json.meta_test_event_code || '').trim();

if (codigoTeste) {
  payloadEnvio.test_event_code = codigoTeste;
}

return [{
  json: {
    fila_id: $json.fila_id,
    tentativas: Number($json.tentativas || 0),
    event_id: $json.event_id,
    chave_cliente: $json.chave_cliente,
    dataset_id: datasetId,
    graph_api_version: versao,
    modo_meta: codigoTeste ? 'TESTE' : 'PRODUCAO',
    url_meta: `https://graph.facebook.com/${versao}/${datasetId}/events`,
    payload_envio: payloadEnvio
  }
}];

// Converte a resposta HTTP em um resultado que pode ser persistido.
const origem = $('PREPARA REQUISIÇÃO META').item.json;
const statusCode = Number($json.statusCode || 0);
const corpo = $json.body ?? $json;
const eventsReceived = Number(corpo?.events_received || 0);

const sucessoHttp = statusCode >= 200 && statusCode < 300;
const sucesso = sucessoHttp && eventsReceived >= 1;

let erro = null;
if (!sucesso) {
  if (corpo?.error?.message) erro = corpo.error.message;
  else if ($json.message) erro = $json.message;
  else erro = `Meta não confirmou recebimento. HTTP ${statusCode || 'sem status'}`;
}

return [{
  json: {
    fila_id: origem.fila_id,
    tentativas: origem.tentativas,
    event_id: origem.event_id,
    chave_cliente: origem.chave_cliente,
    modo_meta: origem.modo_meta,
    sucesso,
    status_code: statusCode,
    events_received: eventsReceived,
    resposta_meta: corpo,
    ultimo_erro: erro
  }
}];
